import React, { useState, useEffect } from "react";
import { db } from "../../firebaseConfig";
import { collection, query, where, getDocs } from "firebase/firestore";
import { useNavigate } from "react-router-dom";
import "./ExamPage.css";

const ExamPage = ({ studentClass }) => {
  const [availableExams, setAvailableExams] = useState([]);
  const [selectedExam, setSelectedExam] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchAvailableExams = async () => {
      setLoading(true);
      try {
        const now = new Date();
        const q = query(
          collection(db, "exams"),
          where("class", "==", studentClass)
        );

        const querySnapshot = await getDocs(q);
        const exams = [];

        querySnapshot.forEach((doc) => {
          const examData = doc.data();
          const examDate = examData.examDate.toDate(); // Convert Firestore Timestamp to JS Date
          const startTime = new Date(examData.startTime); // Use consistent formats in Firestore
          const endTime = new Date(examData.endTime);

          // Check if the exam is available (current time is within start and end time)
          if (now >= startTime && now <= endTime) {
            exams.push({
              id: doc.id,
              subject: examData.subject,
              date: examDate.toDateString(),
              time: `${startTime.toLocaleTimeString()} - ${endTime.toLocaleTimeString()}`,
            });
          }
        });

        setAvailableExams(exams); // Set available exams to state
      } catch (error) {
        console.error("Error fetching available exams:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchAvailableExams(); // Call fetchAvailableExams on component mount
  }, [studentClass]);

  const handleExamSelection = (e) => {
    setSelectedExam(e.target.value);
  };

  const startExam = () => {
    if (selectedExam) {
      navigate(`/exam/${selectedExam}`);
    } else {
      alert("Please select an exam.");
    }
  };

  return (
    <div className="exam-page">
      <h2>Select an Available Exam</h2>
      {loading ? (
        <p>Loading available exams...</p>
      ) : availableExams.length === 0 ? (
        <p>No exams available at this time.</p>
      ) : (
        <>
          <select
            className="exam-dropdown"
            value={selectedExam}
            onChange={handleExamSelection}
          >
            <option value="">Select an exam</option>
            {availableExams.map((exam) => (
              <option key={exam.id} value={exam.subject}>
                {`${exam.subject} - ${exam.date} (${exam.time})`}
              </option>
            ))}
          </select>
          <button
            onClick={startExam}
            className="start-exam-btn"
            disabled={!selectedExam}
          >
            Start Exam
          </button>
        </>
      )}
    </div>
  );
};

export default ExamPage;
